DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:GTC 064", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Both questions are defective in the original page. Q28 gives right-triangle legs AB=12.2 and BC=6 but altitude foot AD=9; these conflict, because the legs require AC≈13.596 and AD=AB²/AC≈10.947, not 9. Q29 literally reads 6≤2x−1≤5, which is impossible, and its four number-line choices are indistinguishable. No intended numerical/letter answer can be verified."}, {"id": "clean:GTC 077", "old_status": "worked_missing_choice", "status": "worked_missing_choice", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Visually checked page 417. 3x−6y=2 has slope 1/2. Choice C, 2y−x=2, has slope 1/2 and a different intercept. Choice D is absent; keep held until the complete source is recovered."}, {"id": "clean:HOA 026", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Original PDF visually rechecked. Page 22 leaves the commission rule above 10 TV sales ambiguous. For 12 sales, 1550 assumes continued commission on all 12; 1530 assumes commission capped at 10; 1430 assumes base plus bonus only. The following h(x) question is cut off. Retained hold rather than inventing a payment rule."}, {"id": "clean:HOA 146", "old_status": "needs_source_repair", "status": "needs_source_repair", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. For g(x)=2x²+10x−10, g(x)=2 has solutions x=1 and x=−6. The quadratic is not one-to-one on the reals and no branch domain is stated. Thus g⁻¹(2) is not well-defined; do not approve −6 merely because it is listed."}, {"id": "clean:HOA 186", "old_status": "defective_choices", "status": "defective_choices", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Visually checked page 108. 2(x+8)+3(x−5)=(x−2)(x+7) reduces to x²=15, whose exact solutions are ±sqrt(15). None of the listed choices is exact. −3.9 is only a one-decimal approximation to one root; the source does not request rounding or restrict the sign. Kept unscored pending a corrected source."}, {"id": "clean:HOA 221", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. The radical bar is absent in this crop. Read as √x+2=2 the answer is x=0 (C), while the matching earlier question HOA 194 clearly shows √(x+2)=2 and gives x=2 (A). Because this copy’s scope cannot be confirmed, do not merge conflicting interpretations or approve a letter; retain the clear HOA 194 version."}, {"id": "clean:HOA 233", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. The source asks for f(−2) but gives f′(x)=(2x−5)(x+1). An arbitrary integration constant prevents determining f(−2). If the prime is a typo, f(−2)=9, but this cannot be silently assumed. Retain pending a corrected source."}, {"id": "clean:MIX 049", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. The shared graph in MIX 048 gives arrival at the shop at 9:15 and a 20-minute stop, hence departure at 9:35. The return-speed clause is clipped, so the arrival time home cannot be determined. The drawn vertical drop is not a physically valid constant-speed return journey; do not infer the answer from the choices."}, {"id": "clean:PSD 026", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. The source gives a 15% overall test-error rate, but does not specify how many errors are false positives versus false negatives, or precisely which denominator the 15% uses. An overall error rate alone does not determine the number actually healthy in the age group. The original answer labels also repeat A. Retain pending complete test/outcome information."}, {"id": "clean:PSD 093", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. This crop contains only the upper portion of a shared chart. The axes, lower data, actual question and choices are absent. It is not a complete question and remains excluded."}, {"id": "clean:PSD 098", "old_status": "needs_source_repair", "status": "needs_source_repair", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. “Cheapest” is ambiguous without specifying total spending versus cost per MB. Over 3 months, totals are $36,$48,$75,$90, so A minimizes spending. Including eligible one-time bonuses, data totals are 4000,6550,10200,12000 MB, so B has the lowest cost per MB (about $0.007328). Preserve both calculations and hold for clarification of the intended quantity."}, {"id": "clean:PSD 144", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. The box plot labels Q1=65 and Q3=80, but asks for an exact count above 85. A box plot does not supply that count, and neither the upper whisker value nor raw scores are provided. Do not assume that 25% exceed 85; retain as insufficient information."}, {"id": "clean:PSD 191", "old_status": "needs_source_repair", "status": "needs_source_repair", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. The text states AD=BC=CD, which directly gives AD/BC=1, absent from the options. For distinct interior points it is also geometrically inconsistent. The likely intended AB=BC=CD would give 3, but that is a different premise and cannot be treated as verified without a corrected original."}, {"id": "clean:PSD 217", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Original full PDF page visually rechecked. The rational function equals 1+2/(x−1), with vertical/horizontal asymptotes x=1,y=1 and intercepts (−1,0),(0,−1). The graph choices are missing; no answer letter can be verified."}, {"id": "est2-papers-2026-09-26:l1june:q05", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Original source image visually checked again. Original diagram has no numerical side length. From tanβ=2/3, the sides are 2k, 3k, k√13 for any k>0. Both √13 and 2√13 are possible hypotenuse lengths. A source side length is required; no unique answer can be verified."}, {"id": "est2-papers-2026-09-26:l1oct:q45", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Original source image visually checked again. For a real angle θ, cos(π/2−θ)=sinθ cannot equal 2/√3>1. There is no real solution. The formal value 4/3 is not a valid answer to the printed premise. Kept excluded pending correction of the source constant."}, {"id": "est2-papers-2026-09-26:l2oct:q04", "old_status": "needs_source_reconstruction", "status": "needs_source_reconstruction", "note": "Recheck of the available source evidence and full-exam search did not resolve this item. Original source image visually checked again. The source crop and PDF contain no shaded-region diagram or description. Curved hemisphere area is 2πr² and total area is 3πr², but neither defines an arbitrary shaded subset. An original diagram is required; no answer can be verified."}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260929') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260929','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260929'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF q.id IS NOT NULL AND NOT (v ? 'before') THEN RAISE EXCEPTION 'Unexpected existing target %',qid; END IF;
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',coalesce(v->>'verification_source',s.source_document||' page '||s.source_page));
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260929','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260929','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-29. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260929';
